#include <random>
#include <iostream>
#include <cstdlib>
#include <cstdio>
#include <vector>
#include <fstream>
#include <algorithm>
#include <cmath>
// hypothesis test for 2x2 maps
int main(int argc, char** argv) {
    std::ifstream f(argv[1]);
    int skip = atoi(argv[2]);
    double expo = atof(argv[3]);
    double OWN1 = atof(argv[4]); // inner blur own weight
    double OWN2 = atof(argv[5]); // final blur own weight
    int mode = atoi(argv[6]);
    unsigned s; int n=0, okS=0, okP=0;
    while (f >> s) {
        std::vector<int> st(4), p(4);
        for (int i = 0; i < 4; i++) f >> st[i];
        for (int i = 0; i < 4; i++) f >> p[i];
        std::mt19937 e(s);
        std::uniform_real_distribution<double> urd(0.0, 1.0);
        for (int i = 0; i < skip; i++) e();
        auto gen = [&]() {
            std::vector<double> fac(5);
            for (int i = 0; i < 5; i++) fac[i] = pow(urd(e), expo);
            // children: fac[1..4] row-major; blur with wrap
            std::vector<double> ch(4), bl(4);
            for (int i = 0; i < 4; i++) ch[i] = fac[1+i];
            for (int a = 0; a < 2; a++) for (int b = 0; b < 2; b++) {
                int mh = (a+1)%2, ph = (a+1)%2, mw = (b+1)%2, pw = (b+1)%2;
                bl[a*2+b] = ch[a*2+b]*OWN1 + (ch[mh*2+b] + ch[ph*2+b] + ch[a*2+mw] + ch[a*2+pw]) * (1-OWN1)/4;
            }
            for (int i = 0; i < 4; i++) bl[i] *= fac[0];
            return bl;
        };
        std::vector<double> pr, sr;
        if (mode == 0) { pr = gen(); sr = gen(); } else { sr = gen(); pr = gen(); }
        auto finalblur = [&](std::vector<double> ch) {
            std::vector<double> bl(4);
            for (int a = 0; a < 2; a++) for (int b = 0; b < 2; b++) {
                int mh = (a+1)%2, ph = (a+1)%2, mw = (b+1)%2, pw = (b+1)%2;
                bl[a*2+b] = ch[a*2+b]*OWN2 + (ch[mh*2+b] + ch[ph*2+b] + ch[a*2+mw] + ch[a*2+pw]) * (1-OWN2)/4;
            }
            return bl;
        };
        pr = finalblur(pr); sr = finalblur(sr);
        // skip to raw 22
        std::mt19937 e2(s); for (int i = 0; i < 22; i++) e2();
        int topP = e2() % 10 + 6; int topS = e2() % 106 + 150;
        double maxP = *std::max_element(pr.begin(), pr.end()), maxS = *std::max_element(sr.begin(), sr.end());
