#include <random>
#include <iostream>
#include <cstdlib>
#include <cstdio>
#include <vector>
#include <algorithm>
#include <cmath>
typedef std::vector<std::vector<double>> Grid;
Grid blur(const Grid& v, double OWN) {
    int R = v.size(), C = v[0].size();
    Grid bl(R, std::vector<double>(C, 0));
    for (int a = 0; a < R; a++) {
        int mhh = (a-1+R)%R, phh = (a+1)%R;
        for (int b = 0; b < C; b++) {
            int mww = (b-1+C)%C, pww = (b+1)%C;
            bl[a][b] += v[a][b]*OWN;
            bl[a][b] += v[mhh][b]*(1-OWN)/4;
            bl[a][b] += v[phh][b]*(1-OWN)/4;
            bl[a][b] += v[a][mww]*(1-OWN)/4;
            bl[a][b] += v[a][pww]*(1-OWN)/4;
        }
    }
    return bl;
}
struct Region {
    double factor;
    std::vector<std::vector<Region*>> children;
    Region(int w, int h, std::mt19937& prg, std::uniform_real_distribution<double>& urd) {
        const int CHUNK = 4;
        factor = pow(urd(prg), 1.5);
        if (w == 1 && h == 1) return;
        int cw = w / CHUNK, ch = h / CHUNK;
        int difW = w - CHUNK*cw, difH = h - CHUNK*ch;
        for (int a = 0; a < CHUNK; a++) {
            int tch = a < difH ? ch+1 : ch;
            if (tch <= 0) continue;
            children.push_back({});
            for (int b = 0; b < CHUNK; b++) {
                int tcw = b < difW ? cw+1 : cw;
                if (tcw <= 0) continue;
                children.back().push_back(new Region(tcw, tch, prg, urd));
            }
        }
        int R = children.size(), C = children[0].size();
        Grid f(R, std::vector<double>(C));
        for (int a = 0; a < R; a++) for (int b = 0; b < C; b++) f[a][b] = children[a][b]->factor;
        f = blur(f, 0.75);
        for (int a = 0; a < R; a++) for (int b = 0; b < C; b++) children[a][b]->factor = f[a][b];
    }
    Grid getFactors() {
        if (children.empty()) return {{factor}};
        int R = children.size(), C = children[0].size();
        std::vector<std::vector<Grid>> cf(R, std::vector<Grid>(C));
        for (int a = 0; a < R; a++) for (int b = 0; b < C; b++) cf[a][b] = children[a][b]->getFactors();
        int W = 0, H = 0;
        for (int a = 0; a < R; a++) H += cf[a][0].size();
        for (int b = 0; b < C; b++) W += cf[0][b][0].size();
        Grid out(H, std::vector<double>(W));
        int y = 0;
        for (int a = 0; a < R; a++) {
            int x = 0;
            for (int b = 0; b < C; b++) {
                for (size_t c = 0; c < cf[a][b].size(); c++) for (size_t d = 0; d < cf[a][b][c].size(); d++) out[y+c][x+d] = cf[a][b][c][d] * factor;
                x += cf[a][b][0].size();
            }
            y += cf[a][0].size();
        }
        return out;
    }
};

int main(int argc, char** argv) {
    unsigned seed = atoi(argv[1]); int w = atoi(argv[2]), h = atoi(argv[3]), n = atoi(argv[4]);
    int kmode = argc > 5 ? atoi(argv[5]) : 0;
    std::mt19937 prg(seed);
    std::uniform_real_distribution<double> urd(0.0, 1.0);
    bool preferHorizontal = prg() % 2;
    int dw, dh;
    if (preferHorizontal) { dh = sqrt(n); while (n % dh != 0) dh--; dw = n / dh; }
    else { dw = sqrt(n); while (n % dw != 0) dw--; dh = n / dw; }
    int cw = w / dw, ch = h / dh;
    if (preferHorizontal) while (ch % n != 0) ch--; else while (cw % n != 0) cw--;
    int mw = cw*dw, mh = ch*dh;
    Region pr(cw, ch, prg, urd);
    Grid prodC = pr.getFactors();
