#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <vector>
#include <string>
#include <map>
#include <functional>
std::vector<std::pair<unsigned,int>> data;
template<class Eng>
void test(const char* name) {
    for (int sd = -2; sd <= 2; sd++) {
        for (int var = 0; var < 12; var++) {
            std::map<int,int> m; std::map<int,int> rm; bool ok = true;
            for (auto& d : data) {
                Eng g((unsigned)(d.first + sd));
                long idx = -1;
                switch (var) {
                    case 0: idx = g()%7; break;
                    case 1: { std::uniform_int_distribution<int> u(0,6); idx = u(g); break; }
                    case 2: { std::uniform_int_distribution<int> u(20,50); idx = u(g)/5; break; }
                    case 3: { std::uniform_int_distribution<int> u(20,50); idx = (int)(u(g)/5.0+0.5); break; }
                    case 4: { std::uniform_real_distribution<double> u(0,1); idx = (int)(u(g)*7); break; }
                    case 5: { g(); idx = g()%7; break; }
                    case 6: { g(); std::uniform_int_distribution<int> u(0,6); idx = u(g); break; }
                    case 7: { std::uniform_int_distribution<int> u(1,7); idx = u(g); break; }
                    case 8: { idx = (g() >> 16) % 7; break; }
                    case 9: { std::uniform_real_distribution<double> u(20,50); idx = (int)(u(g))/5; break; }
                    case 10: { std::uniform_real_distribution<double> u(20,50); idx = (int)(u(g)/5+0.5); break; }
                    case 11: { std::uniform_int_distribution<int> u(0,30); idx = u(g)/5; break; }
                }
                if (m.count(idx) && m[idx] != d.second) { ok = false; break; }
                if (rm.count(d.second) && rm[d.second] != idx) { ok = false; break; }
                m[idx] = d.second; rm[d.second] = idx;
            }
            if (ok) { printf("%s sd=%d var=%d consistent:", name, sd, var); for (auto& kv : m) printf(" %d->%d", kv.first, kv.second); printf("\n"); }
        }
    }
}
struct CRand { CRand(unsigned s){srand(s);} typedef unsigned result_type; static constexpr unsigned min(){return 0;} static constexpr unsigned max(){return RAND_MAX;} unsigned operator()(){return rand();} };
int main() {
    std::ifstream f("/tmp/t/dimtimes.txt");
    unsigned t; int w, h;
    while (f >> t >> w >> h) data.push_back({t, w});
    printf("n=%zu\n", data.size());
    test<std::mt19937>("mt19937");
    test<std::mt19937_64>("mt19937_64");
    test<std::minstd_rand0>("minstd_rand0");
    test<std::minstd_rand>("minstd_rand");
    test<std::ranlux24_base>("ranlux24_base");
    test<std::ranlux48_base>("ranlux48_base");
    test<std::knuth_b>("knuth_b");
    test<CRand>("rand");
    printf("done\n");
}
EOF
