import json, sys
def step(frame, moves, prod, w, h, nplayers):
    # frame: [y][x] -> [owner, strength]; moves: [y][x] -> dir
    # returns new frame
    owner=[[frame[y][x][0] for x in range(w)] for y in range(h)]
    strength=[[frame[y][x][1] for x in range(w)] for y in range(h)]
    pieces=[dict() for _ in range(nplayers)]  # (x,y)->strength
    def getloc(x,y,d):
        if d==1: return (x,(y-1)%h)
        if d==2: return ((x+1)%w,y)
        if d==3: return (x,(y+1)%h)
        if d==4: return ((x-1)%w,y)
        return (x,y)
    # process moves: for each owned cell with a move
    for y in range(h):
        for x in range(w):
            o=owner[y][x]
            if o==0: continue
            d=moves[y][x]
            a=o-1
            if d==0:
                s=strength[y][x]+prod[y][x]
                if s>255: s=255
            else:
                s=strength[y][x]
            nl=getloc(x,y,d)
            if nl in pieces[a]:
                pieces[a][nl]=min(255,pieces[a][nl]+s)
            else:
                pieces[a][nl]=s
            if (x,y) not in pieces[a]:
                pieces[a][(x,y)]=0
            owner[y][x]=0; strength[y][x]=0
    # damage
    toInjure=[dict() for _ in range(nplayers)]
    injureMap=[[0]*w for _ in range(h)]
    for a in range(nplayers):
        for (x,y),s in pieces[a].items():
            for c in range(nplayers):
                if c==a: continue
                for d in range(5):
                    l=getloc(x,y,d)
                    if l in pieces[c]:
                        toInjure[c][l]=toInjure[c].get(l,0)+s
            injureMap[y][x]+=s
            if strength[y][x]>0:
                toInjure[a][(x,y)]=toInjure[a].get((x,y),0)+strength[y][x]
    for a in range(nplayers):
        for l,dmg in toInjure[a].items():
            if l in pieces[a]:
                if dmg>=pieces[a][l]: del pieces[a][l]
                else: pieces[a][l]-=dmg
    for y in range(h):
        for x in range(w):
            if strength[y][x]<injureMap[y][x]: strength[y][x]=0
            else: strength[y][x]-=injureMap[y][x]
            owner[y][x]=0
    for a in range(nplayers):
        for (x,y),s in pieces[a].items():
            owner[y][x]=a+1; strength[y][x]=s
    return [[[owner[y][x],strength[y][x]] for x in range(w)] for y in range(h)]

def check(path, verbose=True):
    d=json.load(open(path))
    w,h=d['width'],d['height']; n=d['num_players']
    bad=0
    for i in range(len(d['moves'])):
        nf=step(d['frames'][i], d['moves'][i], d['productions'], w, h, n)
        if nf!=d['frames'][i+1]:
            bad+=1
            if verbose and bad<=3:
                print("mismatch at frame %d->%d"%(i,i+1))
                for y in range(h):
                    for x in range(w):
                        if nf[y][x]!=d['frames'][i+1][y][x]:
                            print("  (%d,%d): sim %s actual %s  prev %s move %d"%(x,y,nf[y][x],d['frames'][i+1][y][x],d['frames'][i][y][x],d['moves'][i][y][x]))
    print(path, "frames", len(d['frames']), "bad", bad)
    return bad
if __name__=='__main__':
    for p in sys.argv[1:]: check(p)
