    std::vector<std::vector<Region*> > children;

    Region(int w, int h, std::mt19937& prg, std::uniform_real_distribution<double>& urd) {
        const int SPLIT = 4;
        factor = std::pow(urd(prg), 1.5);
        if (w == 1 && h == 1) return;
        int cw = w / SPLIT, ch = h / SPLIT;
        int extraW = w - SPLIT * cw, extraH = h - SPLIT * ch;
        for (int a = 0; a < SPLIT; a++) {
            int tch = a < extraH ? ch + 1 : ch;
            if (tch <= 0) continue;
            children.push_back(std::vector<Region*>());
            for (int b = 0; b < SPLIT; b++) {
                int tcw = b < extraW ? cw + 1 : cw;
                if (tcw <= 0) continue;
                children.back().push_back(new Region(tcw, tch, prg, urd));
            }
        }
        int rows = (int)children.size(), cols = (int)children[0].size();
        Grid f(rows, std::vector<double>(cols));
        for (int a = 0; a < rows; a++) for (int b = 0; b < cols; b++) f[a][b] = children[a][b]->factor;
        f = blurGrid(f, 0.75);
        for (int a = 0; a < rows; a++) for (int b = 0; b < cols; b++) children[a][b]->factor = f[a][b];
    }
    ~Region() {
        for (size_t a = 0; a < children.size(); a++) for (size_t b = 0; b < children[a].size(); b++) delete children[a][b];
    }
    Grid getFactors() const {
        if (children.empty()) return Grid(1, std::vector<double>(1, factor));
        int rows = (int)children.size(), cols = (int)children[0].size();
        std::vector<std::vector<Grid> > cf(rows, std::vector<Grid>(cols));
        for (int a = 0; a < rows; a++) for (int b = 0; b < cols; b++) cf[a][b] = children[a][b]->getFactors();
        int W = 0, H = 0;
        for (int a = 0; a < rows; a++) H += (int)cf[a][0].size();
        for (int b = 0; b < cols; b++) W += (int)cf[0][b][0].size();
        Grid out(H, std::vector<double>(W, 0.0));
        int y = 0;
        for (int a = 0; a < rows; a++) {
            int x = 0;
            for (int b = 0; b < cols; b++) {
                for (size_t c = 0; c < cf[a][b].size(); c++)
                    for (size_t d = 0; d < cf[a][b][c].size(); d++)
                        out[y + c][x + d] = cf[a][b][c][d] * factor;
                x += (int)cf[a][b][0].size();
            }
            y += (int)cf[a][0].size();
        }
        return out;
    }
};

class Map {
public:
    std::vector<std::vector<Site> > contents;
    unsigned short map_width, map_height;

    Map() : map_width(0), map_height(0) {}

    Map(unsigned short width, unsigned short height, unsigned char numberOfPlayers, unsigned int seed) {
        std::mt19937 prg(seed);
        std::uniform_real_distribution<double> urd(0.0, 1.0);

        bool preferHorizontal = prg() % 2;

        int dw, dh;
        if (preferHorizontal) {
            dh = (int)std::sqrt((double)numberOfPlayers);
            while (numberOfPlayers % dh != 0) dh--;
            dw = numberOfPlayers / dh;
        } else {
            dw = (int)std::sqrt((double)numberOfPlayers);
            while (numberOfPlayers % dw != 0) dw--;
            dh = numberOfPlayers / dw;
        }

        int cw = width / dw, ch = height / dh;
        if (preferHorizontal) while (ch % numberOfPlayers != 0) ch--;
        else while (cw % numberOfPlayers != 0) cw--;

        map_width = cw * dw;
        map_height = ch * dh;

        Region prodRegion(cw, ch, prg, urd);
        Grid prodChunk = prodRegion.getFactors();
        Region strRegion(cw, ch, prg, urd);
        Grid strChunk = strRegion.getFactors();

        // Tessellation parameters: columns (or rows) of chunks may be shifted by a uniform amount.
        bool canShift = preferHorizontal ? (dh == 1 || dh % dw == 0) : (dw == 1 || dw % dh == 0);
        unsigned int shiftRoll = canShift ? (unsigned int)prg() : 0u;
        int topProd = (int)(prg() % 10) + 6;
        int topStr = (int)(prg() % 106) + 150;

        Grid prodMap(map_height, std::vector<double>(map_width, 0.0));
        Grid strMap(map_height, std::vector<double>(map_width, 0.0));
        std::vector<std::vector<int> > ownerMap(map_height, std::vector<int>(map_width, 0));

        for (int a = 0; a < dh; a++) for (int b = 0; b < dw; b++) {
            bool flipX = (dw % 2 == 0) && (b % 2 == 1);
            bool flipY = (dh % 2 == 0) && (a % 2 == 1);
            for (int y = 0; y < ch; y++) for (int x = 0; x < cw; x++) {
                int sx = flipX ? cw - 1 - x : x;
                int sy = flipY ? ch - 1 - y : y;
                prodMap[a * ch + y][b * cw + x] = prodChunk[sy][sx];
                strMap[a * ch + y][b * cw + x] = strChunk[sy][sx];
                ownerMap[a * ch + y][b * cw + x] = (sx == cw / 2 && sy == ch / 2) ? a * dw + b + 1 : 0;
            }
        }

        if (canShift) {
            int k = (int)(shiftRoll % numberOfPlayers);
            Grid prod2 = prodMap, str2 = strMap;
            std::vector<std::vector<int> > owner2 = ownerMap;
            if (preferHorizontal) {
                int unit = map_height / dw;
                for (int b = 0; b < dw; b++) for (int y = 0; y < map_height; y++) for (int x = 0; x < cw; x++) {
                    int sy = (y + b * k * unit) % map_height;
                    prod2[y][b * cw + x] = prodMap[sy][b * cw + x];
                    str2[y][b * cw + x] = strMap[sy][b * cw + x];
                    owner2[y][b * cw + x] = ownerMap[sy][b * cw + x];
                }
            } else {
                int unit = map_width / dh;
                for (int a = 0; a < dh; a++) for (int y = 0; y < ch; y++) for (int x = 0; x < map_width; x++) {
                    int sx = (x + a * k * unit) % map_width;
                    prod2[a * ch + y][x] = prodMap[a * ch + y][sx];
                    str2[a * ch + y][x] = strMap[a * ch + y][sx];
                    owner2[a * ch + y][x] = ownerMap[a * ch + y][sx];
                }
            }
            prodMap = prod2; strMap = str2; ownerMap = owner2;
        }

        int iterations = (int)(std::sqrt((double)(map_width * map_height)) / 5) + 1;
        for (int z = 0; z < iterations; z++) {
            prodMap = blurGrid(prodMap, 0.66667);
            strMap = blurGrid(strMap, 0.66667);
        }

        double maxProd = 0, maxStr = 0;
        for (int y = 0; y < map_height; y++) for (int x = 0; x < map_width; x++) {
            maxProd = std::max(maxProd, prodMap[y][x]);
            maxStr = std::max(maxStr, strMap[y][x]);
        }

        contents.assign(map_height, std::vector<Site>(map_width));
        for (int y = 0; y < map_height; y++) for (int x = 0; x < map_width; x++) {
            Site& s = contents[y][x];
            s.owner = (unsigned char)ownerMap[y][x];
            s.production = (unsigned char)(int)std::round(prodMap[y][x] / maxProd * topProd);
            s.strength = (unsigned char)(int)std::round(strMap[y][x] / maxStr * topStr);
            if (s.owner != 0 && s.production == 0) s.production = 1;
        }
    }

    bool inBounds(Location l) const { return l.x < map_width && l.y < map_height; }

    Location getLocation(Location l, unsigned char direction) const {
        if (direction == NORTH) {
            if (l.y == 0) l.y = map_height - 1; else l.y--;
        } else if (direction == EAST) {
            if (l.x == map_width - 1) l.x = 0; else l.x++;
        } else if (direction == SOUTH) {
            if (l.y == map_height - 1) l.y = 0; else l.y++;
        } else if (direction == WEST) {
            if (l.x == 0) l.x = map_width - 1; else l.x--;
        }
        return l;
    }

    Site& getSite(Location l, unsigned char direction = STILL) {
        l = getLocation(l, direction);
        return contents[l.y][l.x];
    }
    const Site& getSite(Location l, unsigned char direction = STILL) const {
        l = getLocation(l, direction);
        return contents[l.y][l.x];
    }
};

} // namespace hlt

#endif
