// A small command line parser reproducing the observable behaviour of the
// environment's option handling (usage text, error messages, combined switches).
#ifndef CMDLINE_HPP
#define CMDLINE_HPP

#include <string>
#include <vector>
#include <list>
#include <sstream>
#include <iostream>
#include <algorithm>
#include <cstdlib>

namespace cmd {

class ArgError {
public:
    std::string text, id;
    ArgError(const std::string& t, const std::string& i) : text(t), id(i) {}
    std::string argId() const { return id == "undefined" ? std::string(" ") : "Argument: " + id; }
};

struct ExitRequest { int status; };

inline char blankChar() { return (char)7; }

class Arg {
public:
    std::string flag, name, desc;
    bool alreadySet;
    bool ignoreable;
    Arg(const std::string& f, const std::string& n, const std::string& d, bool ign) : flag(f), name(n), desc(d), alreadySet(false), ignoreable(ign) {}
    virtual ~Arg() {}
    virtual std::string shortID() const = 0;
    virtual std::string longID() const = 0;
    virtual bool processArg(int* i, std::vector<std::string>& args) = 0;
    virtual bool unlabeled() const { return false; }
    std::string toString() const {
        std::string s;
        if (flag != "") s += "-" + flag + " ";
        s += "(--" + name + ")";
        return s;
    }
    bool argMatches(const std::string& s) const {
        return (flag != "" && s == "-" + flag) || s == "--" + name;
    }
    static bool hasBlanks(const std::string& s) { return s.find_first_of(blankChar()) != std::string::npos; }
    static void trimFlag(std::string& fl, std::string& value) {
        int stop = 0;
        for (int i = 0; (unsigned)i < fl.length(); i++) if (fl[i] == ' ') { stop = i; break; }
        if (stop > 1) { value = fl.substr(stop + 1); fl = fl.substr(0, stop); }
    }
};

static bool g_ignoreRest = false;

template <class T>
inline void extractNumeric(T& dest, const std::string& val) {
    std::istringstream is(val);
    int valuesRead = 0;
    while (is.good()) {
        if (is.peek() != EOF) is >> dest; else break;
        valuesRead++;
    }
    if (is.fail()) throw ArgError("Couldn't read argument value from string '" + val + "'", "");
    if (valuesRead > 1) throw ArgError("More than one valid value parsed from string '" + val + "'", "");
}

template <class T>
class ValueArg : public Arg {
public:
    T value;
    std::string typeDesc;
    ValueArg(const std::string& f, const std::string& n, const std::string& d, const T& def, const std::string& td)
        : Arg(f, n, d, true), value(def), typeDesc(td) {}
    std::string shortID() const {
        std::string id;
        if (flag != "") id = "-" + flag; else id = "--" + name;
        id += " <" + typeDesc + ">";
        return "[" + id + "]";
    }
    std::string longID() const {
        std::string id;
        if (flag != "") { id += "-" + flag + " <" + typeDesc + ">"; id += ",  "; }
        id += "--" + name + " <" + typeDesc + ">";
        return id;
    }
    void extractValue(const std::string& val);
    bool processArg(int* i, std::vector<std::string>& args) {
        if (ignoreable && g_ignoreRest) return false;
        if (hasBlanks(args[*i])) return false;
        std::string fl = args[*i], val = "";
        trimFlag(fl, val);
        if (argMatches(fl)) {
            if (alreadySet) throw ArgError("Argument already set!", toString());
            if (val == "") {
                (*i)++;
                if ((unsigned)(*i) < args.size()) extractValue(args[*i]);
                else throw ArgError("Missing a value for this argument!", toString());
            } else extractValue(val);
            alreadySet = true;
            return true;
        }
        return false;
    }
};

template <class T>
inline void ValueArg<T>::extractValue(const std::string& val) {
    try { extractNumeric(value, val); }
    catch (ArgError& e) { throw ArgError(e.text, toString()); }
}
template <>
inline void ValueArg<std::string>::extractValue(const std::string& val) { value = val; }

class SwitchArg : public Arg {
public:
    bool value;
    int visitor; // 0 none, 1 help, 2 version, 3 ignore rest
    SwitchArg(const std::string& f, const std::string& n, const std::string& d, int vis = 0)
        : Arg(f, n, d, true), value(false), visitor(vis) {}
    std::string shortID() const {
        std::string id;
        if (flag != "") id = "-" + flag; else id = "--" + name;
        return "[" + id + "]";
    }
    std::string longID() const {
        std::string id;
        if (flag != "") { id += "-" + flag; id += ",  "; }
        id += "--" + name;
        return id;
    }
    bool combinedSwitchesMatch(std::string& combined) const {
        if (combined.length() > 0 && combined[0] != '-') return false;
        if (combined.substr(0, 2) == "--") return false;
        if (combined.find_first_of(' ') != std::string::npos) return false;
        for (unsigned i = 1; i < combined.length(); i++)
            if (flag.length() > 0 && combined[i] == flag[0] && combined[i] != '-') {
                combined[i] = blankChar();
                return true;
            }
        return false;
    }
    static bool lastCombined(const std::string& combined) {
        for (unsigned i = 1; i < combined.length(); i++) if (combined[i] != blankChar()) return false;
        return true;
    }
    void commonProcessing() {
        if (alreadySet) throw ArgError("Argument already set!", toString());
        alreadySet = true;
        value = !value;
    }
    bool processArg(int* i, std::vector<std::string>& args) {
        if (ignoreable && g_ignoreRest) return false;
        if (argMatches(args[*i])) {
            commonProcessing();
            return true;
        } else if (combinedSwitchesMatch(args[*i])) {
            if (combinedSwitchesMatch(args[*i])) throw ArgError("Argument already set!", toString());
            commonProcessing();
            return lastCombined(args[*i]);
        }
        return false;
    }
};

class UnlabeledMultiArg : public Arg {
public:
    std::vector<std::string> values;
    std::string typeDesc;
    UnlabeledMultiArg(const std::string& n, const std::string& d, const std::string& td)
        : Arg("", n, d, false), typeDesc(td) {}
    std::string shortID() const { return "<" + typeDesc + "> ..."; }
    std::string longID() const { return "<" + typeDesc + ">  (accepted multiple times)"; }
    bool unlabeled() const { return true; }
    bool processArg(int* i, std::vector<std::string>& args) {
        if (ignoreable && g_ignoreRest) return false;
        if (hasBlanks(args[*i])) return false;
        values.push_back(args[*i]);
        alreadySet = true;
        return true;
    }
};

class CmdLine {
public:
    std::list<Arg*> argList;
    std::string progName, message, version;
    SwitchArg* helpArg;
    SwitchArg* versionArg;
    SwitchArg* ignoreArg;

    CmdLine(const std::string& msg, const std::string& ver) : message(msg), version(ver) {
        helpArg = new SwitchArg("h", "help", "Displays usage information and exits.", 1);
        add(helpArg);
        versionArg = new SwitchArg("", "version", "Displays version information and exits.", 2);
        add(versionArg);
        ignoreArg = new SwitchArg("-", "ignore_rest", "Ignores the rest of the labeled arguments following this flag.", 3);
        add(ignoreArg);
    }
    void add(Arg* a) {
        if (a->unlabeled()) argList.push_back(a);
        else argList.push_front(a);
    }

    static void spacePrint(std::ostream& os, const std::string& s, int maxWidth, int indentSpaces, int secondLineOffset) {
        int len = (int)s.length();
        if ((len + indentSpaces > maxWidth) && maxWidth > 0) {
            int allowedLen = maxWidth - indentSpaces;
            int start = 0;
            while (start < len) {
                int stringLen = std::min<int>(len - start, allowedLen);
                if (stringLen == allowedLen)
                    while (stringLen >= 0 && s[stringLen + start] != ' ' && s[stringLen + start] != ',' && s[stringLen + start] != '|')
                        stringLen--;
                if (stringLen <= 0) stringLen = allowedLen;
                for (int i = 0; i < stringLen; i++)
                    if (s[start + i] == '\n') stringLen = i + 1;
                for (int i = 0; i < indentSpaces; i++) os << " ";
                if (start == 0) {
                    indentSpaces += secondLineOffset;
                    allowedLen -= secondLineOffset;
                }
                os << s.substr(start, stringLen) << std::endl;
                while (start < len && s[stringLen + start] == ' ') start++;
                start += stringLen;
            }
        } else {
            for (int i = 0; i < indentSpaces; i++) os << " ";
            os << s << std::endl;
        }
    }

    void shortUsage(std::ostream& os) const {
        std::string s = progName + " ";
        for (std::list<Arg*>::const_iterator it = argList.begin(); it != argList.end(); ++it)
            s += " " + (*it)->shortID();
        int secondLineOffset = (int)progName.length() + 2;
        if (secondLineOffset > 75 / 2) secondLineOffset = 75 / 2;
        spacePrint(os, s, 75, 3, secondLineOffset);
    }
    void longUsage(std::ostream& os) const {
        for (std::list<Arg*>::const_iterator it = argList.begin(); it != argList.end(); ++it) {
            spacePrint(os, (*it)->longID(), 75, 3, 3);
            spacePrint(os, (*it)->desc, 75, 5, 0);
            os << std::endl;
        }
        os << std::endl;
        spacePrint(os, message, 75, 3, 0);
    }
    void usage(std::ostream& os) const {
        os << std::endl << "USAGE: " << std::endl << std::endl;
        shortUsage(os);
        os << std::endl << std::endl << "Where: " << std::endl << std::endl;
        longUsage(os);
        os << std::endl;
    }
    void printVersion(std::ostream& os) const {
        os << std::endl << progName << "  version: " << version << std::endl << std::endl;
    }
    void failure(const ArgError& e) const {
        std::cerr << "PARSE ERROR: " << e.argId() << std::endl
                  << "             " << e.text << std::endl << std::endl;
        std::cerr << "Brief USAGE: " << std::endl;
        shortUsage(std::cerr);
        std::cerr << std::endl << "For complete USAGE and HELP type: " << std::endl
                  << "   " << progName << " --help" << std::endl << std::endl;
    }

    bool emptyCombined(const std::string& s) const {
        if (s.length() > 0 && s[0] != '-') return false;
        for (unsigned i = 1; i < s.length(); i++) if (s[i] != blankChar()) return false;
        return true;
    }

    void parse(int argc, char** argv) {
        std::vector<std::string> args;
        for (int i = 0; i < argc; i++) args.push_back(argv[i]);
        progName = args.front();
        args.erase(args.begin());
        try {
            for (int i = 0; (unsigned)i < args.size(); i++) {
                bool matched = false;
                for (std::list<Arg*>::iterator it = argList.begin(); it != argList.end(); ++it) {
                    if ((*it)->processArg(&i, args)) {
                        matched = true;
                        SwitchArg* sw = dynamic_cast<SwitchArg*>(*it);
                        if (sw && sw->visitor == 1) { usage(std::cout); throw ExitRequest{0}; }
                        if (sw && sw->visitor == 2) { printVersion(std::cout); throw ExitRequest{0}; }
                        if (sw && sw->visitor == 3) g_ignoreRest = true;
                        break;
                    }
                }
                if (!matched && emptyCombined(args[i])) matched = true;
                if (!matched && !g_ignoreRest) throw ArgError("Couldn't find match for argument", args[i]);
            }
        } catch (ArgError& e) {
            failure(e);
            exit(1);
        } catch (ExitRequest& r) {
            exit(r.status);
        }
    }
};

} // namespace cmd

#endif
