        }
        return (int)millis;
    }

    std::string lastResponse(unsigned char playerTag) {
        std::map<unsigned char, std::string>::iterator it = lastResponses.find(playerTag);
        return it == lastResponses.end() ? std::string() : it->second;
    }

private:
    std::map<unsigned char, std::string> lastResponses;

    static bool deserializeMoves(const std::string& str, const hlt::Map& m, std::map<hlt::Location, unsigned char>* moves) {
        moves->clear();
        for (size_t i = 0; i < str.size(); i++) {
