// Process management and pipe based communication with the bots.
#ifndef NETWORKING_HPP
#define NETWORKING_HPP

#include <string>
#include <vector>
#include <map>
#include <set>
#include <sstream>
#include <iostream>
#include <chrono>
#include <thread>
#include <mutex>
#include <cstring>
#include <cerrno>

#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/select.h>
#include <sys/time.h>

#include "hlt_map.hpp"

struct BotProcess {
    pid_t pid;
    int writeFd;  // environment -> bot stdin
    int readFd;   // bot stdout/stderr -> environment
    bool alive;
};

struct ReadResult {
    bool ok;          // a complete line was received before the deadline
    std::string data; // the line (without newline) or the partial data received so far
};

class Networking {
public:
    std::vector<BotProcess> bots;
    std::vector<std::string> playerLogs;
    std::mutex outputMutex;
    bool quiet;

    Networking() : quiet(false) {}

    // Launches a bot through the shell, in its own process group.
    void startAndConnectBot(const std::string& command) {
        int toBot[2], fromBot[2];
        if (pipe(toBot) != 0 || pipe(fromBot) != 0) {
            std::cerr << "Could not create pipes for bot." << std::endl;
            exit(1);
        }
        pid_t pid = fork();
        if (pid < 0) {
            std::cerr << "Could not fork bot process." << std::endl;
            exit(1);
        }
        if (pid == 0) {
            setpgid(0, 0);
            dup2(toBot[0], STDIN_FILENO);
            dup2(fromBot[1], STDOUT_FILENO);
            dup2(fromBot[1], STDERR_FILENO);
            close(toBot[0]); close(toBot[1]); close(fromBot[0]); close(fromBot[1]);
            execl("/bin/sh", "sh", "-c", command.c_str(), (char*)NULL);
            _exit(127);
        }
        close(toBot[0]);
        close(fromBot[1]);
        BotProcess bp;
        bp.pid = pid;
        bp.writeFd = toBot[1];
        bp.readFd = fromBot[0];
        bp.alive = true;
        bots.push_back(bp);
        playerLogs.push_back(std::string());
    }

    int numberOfPlayers() const { return (int)bots.size(); }

    void sendString(unsigned char playerTag, const std::string& s) {
        BotProcess& bp = bots[playerTag - 1];
        std::string msg = s + "\n";
        size_t off = 0;
        while (off < msg.size()) {
            ssize_t n = write(bp.writeFd, msg.data() + off, msg.size() - off);
            if (n <= 0) {
                if (n < 0 && errno == EINTR) continue;
                break;
            }
            off += (size_t)n;
        }
    }

    // Reads a single line; waits at most timeoutMillis (negative = forever).
    ReadResult getString(unsigned char playerTag, long long timeoutMillis) {
        BotProcess& bp = bots[playerTag - 1];
        ReadResult result;
        result.ok = false;
        std::chrono::steady_clock::time_point deadline = std::chrono::steady_clock::now() + std::chrono::milliseconds(timeoutMillis);
        char c;
        while (true) {
            if (timeoutMillis >= 0) {
                std::chrono::steady_clock::time_point now = std::chrono::steady_clock::now();
                if (now >= deadline) return result;
                long long remain = std::chrono::duration_cast<std::chrono::microseconds>(deadline - now).count();
                fd_set set;
                FD_ZERO(&set);
                FD_SET(bp.readFd, &set);
                struct timeval tv;
                tv.tv_sec = remain / 1000000;
                tv.tv_usec = remain % 1000000;
                int sel = select(bp.readFd + 1, &set, NULL, NULL, &tv);
                if (sel < 0) {
                    if (errno == EINTR) continue;
                    return result;
                }
                if (sel == 0) return result;
            }
            ssize_t n = read(bp.readFd, &c, 1);
            if (n < 0) {
                if (errno == EINTR) continue;
                // Unexpected failure: wait out the remaining time like a silent bot.
                if (timeoutMillis >= 0) { std::this_thread::sleep_until(deadline); return result; }
                std::this_thread::sleep_for(std::chrono::milliseconds(50));
                continue;
            }
            if (n == 0) {
                // End of stream: the bot will never answer; behave like a timeout.
                if (timeoutMillis >= 0) { std::this_thread::sleep_until(deadline); return result; }
                std::this_thread::sleep_for(std::chrono::milliseconds(1000));
                continue;
            }
            if (c == '\n') break;
            result.data.push_back(c);
        }
        if (!result.data.empty() && result.data[result.data.size() - 1] == '\r') result.data.erase(result.data.size() - 1);
        result.ok = true;
        return result;
    }

    // Reads whatever output is still available without blocking.
    std::string drainOutput(unsigned char playerTag) {
        BotProcess& bp = bots[playerTag - 1];
        std::string out;
        int flags = fcntl(bp.readFd, F_GETFL, 0);
        fcntl(bp.readFd, F_SETFL, flags | O_NONBLOCK);
        char buf[4096];
        while (true) {
            ssize_t n = read(bp.readFd, buf, sizeof(buf));
            if (n > 0) { out.append(buf, (size_t)n); continue; }
            if (n < 0 && errno == EINTR) continue;
            break;
        }
        fcntl(bp.readFd, F_SETFL, flags);
        return out;
    }

    void killPlayer(unsigned char playerTag) {
        BotProcess& bp = bots[playerTag - 1];
        if (!bp.alive) return;
        kill(-bp.pid, SIGKILL);
        kill(bp.pid, SIGKILL);
        int status;
        waitpid(bp.pid, &status, 0);
        bp.alive = false;
    }

    void closePlayer(unsigned char playerTag) {
        BotProcess& bp = bots[playerTag - 1];
        if (bp.readFd >= 0) { close(bp.readFd); bp.readFd = -1; }
        if (bp.writeFd >= 0) { close(bp.writeFd); bp.writeFd = -1; }
    }

    // Appends the standard "errored" epilogue to a player's log and terminates the bot.
    void failPlayer(unsigned char playerTag, const std::string& lastResponse) {
        std::string& log = playerLogs[playerTag - 1];
        log += "ERRORED!\n";
        if (lastResponse.empty()) log += "No response received.";
        else log += "Response received (if any):\n" + lastResponse;
        killPlayer(playerTag);
        std::string rest = drainOutput(playerTag);
        if (!rest.empty()) {
            log += "\n --- Bot was killed. Below is the rest of its output (if any): ---\n" + rest + "\n --- End bot output ---";
        }
    }

    static std::string serializeMap(const hlt::Map& m) {
        std::ostringstream oss;
        // Run-length encoded owners followed by every strength.
        int counter = 0;
        int currentOwner = -1;
        for (int y = 0; y < m.map_height; y++) for (int x = 0; x < m.map_width; x++) {
            const hlt::Site& s = m.contents[y][x];
            if (currentOwner == -1) { currentOwner = s.owner; counter = 1; }
            else if (s.owner == currentOwner) counter++;
            else {
                oss << counter << ' ' << currentOwner << ' ';
                currentOwner = s.owner;
                counter = 1;
            }
        }
        if (currentOwner != -1) oss << counter << ' ' << currentOwner << ' ';
        for (int y = 0; y < m.map_height; y++) for (int x = 0; x < m.map_width; x++) oss << (int)m.contents[y][x].strength << ' ';
        return oss.str();
    }

    static std::string serializeProductions(const hlt::Map& m) {
        std::ostringstream oss;
        for (int y = 0; y < m.map_height; y++) for (int x = 0; x < m.map_width; x++) oss << (int)m.contents[y][x].production << ' ';
        return oss.str();
    }

    // Returns the response time in milliseconds, or -1 on failure.
    int handleInitNetworking(unsigned char playerTag, const hlt::Map& m, bool ignoreTimeout, std::string* playerName) {
        std::string& log = playerLogs[playerTag - 1];
        std::ostringstream header;
        header << (int)playerTag;
        sendString(playerTag, header.str());
        std::ostringstream dims;
        dims << m.map_width << ' ' << m.map_height << ' ';
        sendString(playerTag, dims.str());
        sendString(playerTag, serializeProductions(m));
        sendString(playerTag, serializeMap(m));
        if (!quiet) {
            std::lock_guard<std::mutex> lock(outputMutex);
            std::cout << "Init Message sent to player " << (int)playerTag << "." << std::endl;
        }
        std::chrono::steady_clock::time_point start = std::chrono::steady_clock::now();
        ReadResult r = getString(playerTag, ignoreTimeout ? -1 : 30000);
        std::chrono::steady_clock::time_point end = std::chrono::steady_clock::now();
        long long millis = std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count();
        log += " --- Init ---\n";
        if (!r.ok) {
            log += "\n";
            lastResponses[playerTag] = r.data;
            return -1;
        }
        log += r.data + "\n --- Bot used " + std::to_string(millis) + " milliseconds ---\n";
        if (!quiet) {
            std::lock_guard<std::mutex> lock(outputMutex);
            std::cout << "Init Message received from player " << (int)playerTag << ", " << r.data << "." << std::endl;
        }
        *playerName = r.data.substr(0, 30);
        return (int)millis;
    }

    // Returns the response time in milliseconds, or -1 on failure.
    int handleFrameNetworking(unsigned char playerTag, unsigned short turnNumber, const hlt::Map& m, bool ignoreTimeout, std::map<hlt::Location, unsigned char>* moves) {
        std::string& log = playerLogs[playerTag - 1];
        sendString(playerTag, serializeMap(m));
        std::chrono::steady_clock::time_point start = std::chrono::steady_clock::now();
        ReadResult r = getString(playerTag, ignoreTimeout ? -1 : 1500);
        std::chrono::steady_clock::time_point end = std::chrono::steady_clock::now();
        long long millis = std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count();
        log += "-----------------------------------------------------------------------------\n --- Frame #" + std::to_string(turnNumber) + " ---\n";
        if (!r.ok) {
            log += "\n";
            lastResponses[playerTag] = r.data;
            return -1;
        }
        log += r.data + "\n --- Bot used " + std::to_string(millis) + " milliseconds ---\n";
        lastResponses[playerTag] = r.data;
        if (!deserializeMoves(r.data, m, moves)) {
            if (!quiet) {
                std::lock_guard<std::mutex> lock(outputMutex);
                std::cout << "Bot sent an invalid character - ejecting from game." << std::endl;
            }
            return -1;
        }
        return (int)millis;
    }

    std::string lastResponse(unsigned char playerTag) {
        std::map<unsigned char, std::string>::iterator it = lastResponses.find(playerTag);
        return it == lastResponses.end() ? std::string() : it->second;
    }

private:
    std::map<unsigned char, std::string> lastResponses;

    static bool deserializeMoves(const std::string& str, const hlt::Map& m, std::map<hlt::Location, unsigned char>* moves) {
        moves->clear();
        for (size_t i = 0; i < str.size(); i++) {
            char c = str[i];
            if (!(c >= '0' && c <= '9') && c != ' ') return false;
        }
        std::istringstream iss(str);
        int x, y, d;
        while (iss >> x >> y >> d) {
            if (x < 0 || y < 0 || x >= m.map_width || y >= m.map_height) continue;
            hlt::Location l;
            l.x = (unsigned short)x;
            l.y = (unsigned short)y;
            (*moves)[l] = (unsigned char)d;
        }
        return true;
    }
};

#endif
