                std::map<hlt::Location, unsigned char>::iterator existing = pm.find(l);
                if (existing != pm.end()) {
                    if ((int)existing->second + s.strength <= 255) existing->second += s.strength;
                    else existing->second = 255;
                } else pm[l] = s.strength;
                s.owner = 0;
                s.strength = 0;
            }
        }

