                    for (unsigned char d = 0; d <= 4; d++) {
                        hlt::Location target = game_map.getLocation(b->first, d);
                        if (pieces[c].count(target)) toInjure[c][target] += b->second;
                    }
                }
                injureMap[b->first.y][b->first.x] += b->second;
                hlt::Site& site = game_map.getSite(b->first);
                if (site.strength > 0) toInjure[a][b->first] += site.strength;
