// Game state, turn processing, ranking and replay output.
#ifndef HALITE_HPP
#define HALITE_HPP

#include <vector>
#include <string>
#include <map>
#include <set>
#include <algorithm>
#include <functional>
#include <future>
#include <fstream>
#include <stdexcept>
#include <iostream>

#include "hlt_map.hpp"
#include "networking.hpp"
#include "json_writer.hpp"

struct PlayerStatistics {
    int tag;
    int rank;
    int alive_frame_count;
};

struct GameStatistics {
    std::vector<PlayerStatistics> player_statistics;
    std::string output_filename;
    std::set<unsigned short> timeout_tags;
    std::vector<std::string> timeout_log_filenames;
};

class Halite {
public:
    Halite(unsigned short width, unsigned short height, unsigned int seed, unsigned char nPlayersForMap, Networking& net, bool ignoreTimeout_, bool quiet_)
        : networking(net), ignore_timeout(ignoreTimeout_), quiet_output(quiet_) {
        number_of_players = (unsigned char)networking.numberOfPlayers();
        game_map = hlt::Map(width, height, nPlayersForMap, seed);
        // Only the tiles belonging to actual players keep an owner.
        for (int y = 0; y < game_map.map_height; y++) for (int x = 0; x < game_map.map_width; x++)
            if (game_map.contents[y][x].owner > number_of_players) game_map.contents[y][x].owner = 0;
        turn_number = 0;
        player_names = std::vector<std::string>(number_of_players);
        player_moves = std::vector<std::map<hlt::Location, unsigned char> >(number_of_players);
        full_frames.push_back(game_map);
    }

    GameStatistics runGame(std::vector<std::string>* names, unsigned int seed, unsigned int id, const std::string& replayDirectory, bool produceReplay) {
        std::vector<bool> result(number_of_players, true);
        std::vector<unsigned int> rankings;

        alive_frame_count = std::vector<int>(number_of_players, 1);
        last_territory_count = std::vector<unsigned int>(number_of_players, 1);
        full_territory_count = std::vector<unsigned int>(number_of_players, 1);
        timeout_tags.clear();

        // Initialisation: every bot is contacted concurrently.
        std::vector<std::future<int> > initThreads(number_of_players);
        for (unsigned char a = 0; a < number_of_players; a++) {
            initThreads[a] = std::async(std::launch::async, &Networking::handleInitNetworking, &networking, (unsigned char)(a + 1), game_map, ignore_timeout, &player_names[a]);
        }
        for (unsigned char a = 0; a < number_of_players; a++) {
            int time = initThreads[a].get();
            if (time == -1) {
                if (!quiet_output) std::cout << "Bot #" << (int)(a + 1) << " timeout or error (Unix) 0" << std::endl;
                networking.failPlayer(a + 1, networking.lastResponse(a + 1));
                timeout_tags.insert(a + 1);
                player_names[a] = "Bot #" + std::to_string(a + 1) + "; timed out during Init";
                result[a] = false;
                alive_frame_count[a] = 0;
                for (int y = 0; y < game_map.map_height; y++) for (int x = 0; x < game_map.map_width; x++)
                    if (game_map.contents[y][x].owner == a + 1) game_map.contents[y][x].owner = 0;
            }
        }
        if (names != NULL) for (unsigned char a = 0; a < number_of_players; a++) player_names[a] = (*names)[a].substr(0, 30);

        // Players that never answered are ranked at the very bottom.
        {
            std::vector<unsigned int> dead;
            for (unsigned char a = 0; a < number_of_players; a++) if (!result[a]) dead.push_back(a);
            sortByTerritory(dead);
            for (size_t i = 0; i < dead.size(); i++) rankings.push_back(dead[i]);
        }

        const int maxTurnNumber = (int)(std::sqrt((double)(game_map.map_width * game_map.map_height)) * 10);

        while (turn_number < maxTurnNumber && keepPlaying(result)) {
            turn_number++;
            if (!quiet_output) std::cout << "Turn " << turn_number << "\n";
            std::vector<bool> newResult = processNextFrame(result);
            std::vector<unsigned int> newRankings;
            for (unsigned char a = 0; a < number_of_players; a++) if (result[a] && !newResult[a]) newRankings.push_back(a);
            sortByTerritory(newRankings);
            for (size_t i = 0; i < newRankings.size(); i++) rankings.push_back(newRankings[i]);
            result = newResult;
        }
        std::vector<unsigned int> survivors;
        for (unsigned char a = 0; a < number_of_players; a++) if (result[a]) survivors.push_back(a);
        sortByTerritory(survivors);
        for (size_t i = 0; i < survivors.size(); i++) rankings.push_back(survivors[i]);
        std::reverse(rankings.begin(), rankings.end());

        GameStatistics stats;
        for (unsigned char a = 0; a < number_of_players; a++) {
            PlayerStatistics p;
            p.tag = a + 1;
            p.rank = (int)(std::find(rankings.begin(), rankings.end(), a) - rankings.begin()) + 1;
            p.alive_frame_count = alive_frame_count[a] - 1;
            stats.player_statistics.push_back(p);
        }
        stats.timeout_tags = timeout_tags;

        if (produceReplay) {
            stats.output_filename = replayDirectory + std::to_string(id) + '-' + std::to_string(seed) + ".hlt";
            output(stats.output_filename);
            if (!quiet_output) std::cout << "Map seed was " << seed << std::endl << "Opening a file at " << stats.output_filename << std::endl;
            else std::cout << stats.output_filename << ' ' << seed << std::endl;
        }

        for (std::set<unsigned short>::iterator a = timeout_tags.begin(); a != timeout_tags.end(); ++a) {
            std::string filename = std::to_string(*a) + '-' + std::to_string(id) + ".log";
            stats.timeout_log_filenames.push_back(filename);
            std::ofstream file(filename.c_str(), std::ios_base::binary);
            file << networking.playerLogs[*a - 1];
            file.flush();
            file.close();
        }

        // Make sure every bot is gone.
        for (unsigned char a = 0; a < number_of_players; a++) {
            networking.killPlayer(a + 1);
            networking.closePlayer(a + 1);
        }
        return stats;
    }

    const std::vector<std::string>& names() const { return player_names; }

private:
    Networking& networking;
    bool ignore_timeout;
    bool quiet_output;
    unsigned char number_of_players;
    hlt::Map game_map;
    unsigned short turn_number;
    std::vector<std::string> player_names;
    std::vector<std::map<hlt::Location, unsigned char> > player_moves;
    std::vector<hlt::Map> full_frames;
    std::vector<std::vector<std::vector<unsigned char> > > full_player_moves;
