    std::vector<unsigned int> last_territory_count;
    std::vector<unsigned int> full_territory_count;
    std::set<unsigned short> timeout_tags;

    bool keepPlaying(const std::vector<bool>& alive) const {
        if (number_of_players == 1) {
            return last_territory_count[0] < (unsigned int)(game_map.map_width * game_map.map_height);
        }
        return std::count(alive.begin(), alive.end(), true) > 1;
    }

    void sortByTerritory(std::vector<unsigned int>& v) const {
        std::stable_sort(v.begin(), v.end(), [&](unsigned int u1, unsigned int u2) -> bool {
            if (last_territory_count[u1] == last_territory_count[u2]) return full_territory_count[u1] < full_territory_count[u2];
            return last_territory_count[u1] < last_territory_count[u2];
        });
    }

    std::vector<bool> processNextFrame(const std::vector<bool>& alive) {
        std::vector<std::future<int> > frameThreads(number_of_players);
        for (unsigned char a = 0; a < number_of_players; a++) {
            if (alive[a]) {
