                hlt::Site& s = game_map.getSite(b->first);
                s.owner = a + 1;
                s.strength = b->second;
            }
        }

        full_frames.push_back(game_map);
        full_player_moves.push_back(movesThisFrame);

        std::vector<bool> stillAlive(number_of_players, false);
        std::vector<unsigned int> territory(number_of_players, 0);
        for (int y = 0; y < game_map.map_height; y++) for (int x = 0; x < game_map.map_width; x++) {
