#include <ctime>
#include <cstdlib>
#include <csignal>

#include "cmdline.hpp"
#include "hlt_map.hpp"
#include "networking.hpp"
#include "halite.hpp"

struct Dimensions {
    int width, height;
    Dimensions() : width(0), height(0) {}
};

inline std::istream& operator>>(std::istream& is, Dimensions& d) {
    is >> d.width >> d.height;
    return is;
}

static void printPlayerLine(const std::string& cmd, bool flush) {
    if (flush) std::cout << cmd << std::endl;
    else std::cout << cmd << "\n";
}

int main(int argc, char** argv) {
    cmd::CmdLine parser("Halite Game Environment", "1.2");

    cmd::SwitchArg quietSwitch("q", "quiet", "Runs game in quiet mode, producing machine-parsable output.");
    cmd::SwitchArg overrideSwitch("o", "override", "Overrides player-sent names using cmd args [SERVER ONLY].");
    cmd::SwitchArg timeoutSwitch("t", "timeout", "Causes game environment to ignore timeouts (give all bots infinite time).");
    cmd::SwitchArg noReplaySwitch("r", "noreplay", "Turns off the replay generation.");
    cmd::ValueArg<int> nPlayersArg("n", "nplayers", "Create a map that will accommodate n players [SINGLE PLAYER MODE ONLY].", 1, "{1,2,3,4,5,6}");
    cmd::ValueArg<Dimensions> dimensionArgs("d", "dimensions", "The dimensions of the map.", Dimensions(), "a string containing two space-seprated positive integers");
    cmd::ValueArg<unsigned int> seedArg("s", "seed", "The seed for the map generator.", 0, "positive integer");
    cmd::ValueArg<std::string> replayDirectoryArg("i", "replaydirectory", "The path to directory for replay output.", ".", "path to directory");
    cmd::UnlabeledMultiArg otherArgs("NonspecifiedArgs", "Start commands for bots.", "Array of strings");

    parser.add(&quietSwitch);
    parser.add(&overrideSwitch);
    parser.add(&timeoutSwitch);
    parser.add(&noReplaySwitch);
    parser.add(&nPlayersArg);
    parser.add(&dimensionArgs);
    parser.add(&seedArg);
    parser.add(&replayDirectoryArg);
    parser.add(&otherArgs);
    parser.parse(argc, argv);

    bool quiet = quietSwitch.value;
    bool overrideNames = overrideSwitch.value;
    bool ignoreTimeout = timeoutSwitch.value;
    bool produceReplay = !noReplaySwitch.value;
    int nPlayersForMap = nPlayersArg.value;
    Dimensions dims = dimensionArgs.value;
    unsigned int seed = seedArg.value;
    std::string replayDirectory = replayDirectoryArg.value;
    std::vector<std::string> unlabeled = otherArgs.values;

    unsigned int id = (unsigned int)time(NULL);
    if (seed == 0) {
        long long micros = std::chrono::duration_cast<std::chrono::microseconds>(std::chrono::high_resolution_clock::now().time_since_epoch()).count();
        seed = (unsigned int)(micros % 4294967295LL);
    }

    if (replayDirectory.empty() || replayDirectory[replayDirectory.size() - 1] != '/') replayDirectory += '/';

    int mapWidth = dims.width, mapHeight = dims.height;
    if (mapWidth == 0 && mapHeight == 0) {
        static const int choices[] = { 20, 25, 25, 30, 30, 30, 35, 35, 35, 35, 40, 40, 40, 45, 45, 50 };
        srand((unsigned int)time(NULL));
        mapWidth = mapHeight = choices[rand() % 16];
    }

    Networking networking;
    networking.quiet = quiet;
    std::vector<std::string> names;
    std::vector<std::string> commands;

    if (overrideNames) {
        if (unlabeled.size() < 4 || unlabeled.size() % 2 != 0) {
            std::cout << "Invalid number of player parameters with override switch enabled.  Override intended for server use only." << std::endl;
            exit(1);
        }
        for (size_t a = 0; a < unlabeled.size(); a += 2) {
            commands.push_back(unlabeled[a]);
            names.push_back(unlabeled[a + 1]);
        }
    } else {
        commands = unlabeled;
    }

    for (size_t a = 0; a < commands.size(); a++) {
        if (!overrideNames) printPlayerLine(commands[a], true);
        if (!quiet) printPlayerLine(commands[a], false);
    }

    if (commands.empty()) {
        std::cout << "Please provide the launch command string for at least one bot." << std::endl
                  << "Use the --help flag for usage details." << std::endl;
        exit(1);
    }
    if (commands.size() > 1 && nPlayersForMap != 1) {
        std::cout << std::endl << "Only single-player mode enables specified n-player maps.  When entering multiple bots, please do not try to specify n." << std::endl << std::endl;
        exit(1);
    }
    if (commands.size() == 1 && (nPlayersForMap < 1 || nPlayersForMap > 6)) {
        std::cout << std::endl << "A map can only accommodate between 1 and 6 players." << std::endl << std::endl;
        exit(1);
    }
    if (commands.size() > 6) {
        std::cout << std::endl << "A map can only accommodate between 1 and 6 players." << std::endl << std::endl;
        exit(1);
    }

    for (size_t a = 0; a < commands.size(); a++) networking.startAndConnectBot(commands[a]);

    unsigned char mapPlayers = commands.size() > 1 ? (unsigned char)commands.size() : (unsigned char)nPlayersForMap;

    // Degenerate geometry crashes the generator.
    {
        if (mapWidth <= 0 || mapHeight <= 0) raise(SIGSEGV);
        std::mt19937 probe(seed);
        bool preferHorizontal = probe() % 2;
        int dw, dh, n = mapPlayers;
        if (preferHorizontal) { dh = (int)std::sqrt((double)n); while (n % dh != 0) dh--; dw = n / dh; }
        else { dw = (int)std::sqrt((double)n); while (n % dw != 0) dw--; dh = n / dw; }
        int cw = mapWidth / dw, ch = mapHeight / dh;
        if (preferHorizontal) while (ch % n != 0) ch--; else while (cw % n != 0) cw--;
        if (cw <= 0 || ch <= 0) raise(SIGSEGV);
    }

    Halite game((unsigned short)mapWidth, (unsigned short)mapHeight, seed, mapPlayers, networking, ignoreTimeout, quiet);

    std::cout << mapWidth << ' ' << mapHeight << std::endl;

    GameStatistics stats = game.runGame(overrideNames ? &names : NULL, seed, id, replayDirectory, produceReplay);

    if (!quiet) {
        for (size_t a = 0; a < stats.player_statistics.size(); a++) {
            std::cout << "Player #" << stats.player_statistics[a].tag << ", " << game.names()[a]
                      << ", came in rank #" << stats.player_statistics[a].rank
                      << " and was last alive on frame #" << stats.player_statistics[a].alive_frame_count << "!" << std::endl;
        }
    } else {
        for (size_t a = 0; a < stats.player_statistics.size(); a++) {
            std::cout << stats.player_statistics[a].tag << ' ' << stats.player_statistics[a].rank << ' ' << stats.player_statistics[a].alive_frame_count << std::endl;
        }
        std::string tags;
        for (std::set<unsigned short>::const_iterator it = stats.timeout_tags.begin(); it != stats.timeout_tags.end(); ++it) {
            if (!tags.empty()) tags += ' ';
            tags += std::to_string(*it);
        }
        std::cout << tags << ' ' << std::endl;
        std::string logs;
        for (size_t a = 0; a < stats.timeout_log_filenames.size(); a++) {
            if (!logs.empty()) logs += ' ';
            logs += stats.timeout_log_filenames[a];
        }
        std::cout << logs << ' ';
        std::cout.flush();
    }
    return 0;
}
EOF
